INSERT INTO titles (id,name,kind,year,genre,maturity_rating,rating,synopsis,poster,backdrop,video_url,duration,top10_rank,language,language_name) VALUES (37,'Overdo','series','2026','Drama','TV-14',9.0,'In Republican Shanghai, Murong Qingyi, a warlord’s son swapped at birth, endures years of torment. His life changes when Ren Susu saves him, but tragedy strikes her family because of it. Years later, love sparks between them, but Ren Susu fakes her death to save another, leaving Qingyi heartbroken. Three years on, she returns as his future sister-in-law. Love, hate, betrayal, and old wounds resurface. As war looms, the two must defy fate together, but can love survive a nation’s fall?','/assets/posters/tv_289139.jpg','/assets/backdrops/tv_289139.jpg','/assets/video/clip_18972999.mp4',2700,2,'zh','Chinese') ON CONFLICT (id) DO NOTHING;
