INSERT INTO titles (id,name,kind,year,genre,maturity_rating,rating,synopsis,poster,backdrop,video_url,duration,top10_rank,language,language_name) VALUES (58,'Law & Order: Special Victims Unit','series','1999','Crime','TV-14',8.0,'In the criminal justice system, sexually-based offenses are considered especially heinous. In New York City, the dedicated detectives who investigate these vicious felonies are members of an elite squad known as the Special Victims Unit. These are their stories.','/assets/posters/tv_2734.jpg','/assets/backdrops/tv_2734.jpg','/assets/video/clip_30070091.mp4',2700,NULL,'en','English') ON CONFLICT (id) DO NOTHING;
