INSERT INTO titles (id,name,kind,year,genre,maturity_rating,rating,synopsis,poster,backdrop,video_url,duration,top10_rank,language,language_name) VALUES (59,'The Late Show with Stephen Colbert','series','2015','Comedy','TV-14',6.1,'Stephen Colbert brings his signature satire and comedy to The Late Show with Stephen Colbert, the #1 show in late night, where he talks with an eclectic mix of guests about what is new and relevant in the worlds of politics, entertainment, business, music, technology, and more. Featuring bandleader Jon Batiste with his band Stay Human, the Emmy Award-nominated show is broadcast from the historic Ed Sullivan Theater.','/assets/posters/tv_63770.jpg','/assets/backdrops/tv_63770.jpg','/assets/video/clip_30997958.mp4',2700,NULL,'en','English') ON CONFLICT (id) DO NOTHING;
