INSERT INTO episodes (id,title_id,season,number,name,synopsis,duration,thumbnail) VALUES (7,22,1,1,'Chapter One','The Targaryen dynasty is at the absolute apex of its power, with more than 15 dragons under their yoke. Most empires crumble from such heights. In the case of the Targaryens, their slow fall begins when King Viserys breaks with a century of tradition by naming his daughter Rhaenyra heir to the Iron Throne. But when Viserys later fathers a son, the court is shocked when Rhaenyra retains her status as his heir, and seeds of division sow friction across the realm.',2700,'/assets/backdrops/tv_94997.jpg') ON CONFLICT (id) DO NOTHING;
