INSERT INTO episodes (id,title_id,season,number,name,synopsis,duration,thumbnail) VALUES (73,33,1,1,'Chapter One','When a 34-year-old underachiever gets run over by a truck, his story doesn''t end there. Reincarnated in a new world as an infant, Rudy will seize every opportunity to live the life he''s always wanted. Armed with new friends, some freshly acquired magical abilities, and the courage to do the things he''s always dreamed of, he''s embarking on an epic adventure—with all of his past experience intact!',2700,'/assets/backdrops/tv_94664.jpg') ON CONFLICT (id) DO NOTHING;
