INSERT INTO episodes (id,title_id,season,number,name,synopsis,duration,thumbnail) VALUES (79,34,1,1,'Chapter One','Unravel the mystery of a nightmarish town in middle America that traps all those who enter. As the unwilling residents fight to keep a sense of normalcy and search for a way out, they must also survive the threats of the surrounding forest – including the terrifying creatures that come out when the sun goes down.',2700,'/assets/backdrops/tv_124364.jpg') ON CONFLICT (id) DO NOTHING;
