INSERT INTO episodes (id,title_id,season,number,name,synopsis,duration,thumbnail) VALUES (85,35,1,1,'Chapter One','Set in Texas, this animated series follows the life of propane salesman Hank Hill, who lives with his overly confident substitute Spanish teacher wife Peggy, wannabe comedian son Bobby, and naive niece Luanne. Hank has conservative views about God, family, and country, but his values and ethics are often challenged by the situations he, his family, and his beer-drinking neighbors/buddies find themselves in.',2700,'/assets/backdrops/tv_2122.jpg') ON CONFLICT (id) DO NOTHING;
