INSERT INTO episodes (id,title_id,season,number,name,synopsis,duration,thumbnail) VALUES (97,37,1,1,'Chapter One','In Republican Shanghai, Murong Qingyi, a warlord’s son swapped at birth, endures years of torment. His life changes when Ren Susu saves him, but tragedy strikes her family because of it. Years later, love sparks between them, but Ren Susu fakes her death to save another, leaving Qingyi heartbroken. Three years on, she returns as his future sister-in-law. Love, hate, betrayal, and old wounds resurface. As war looms, the two must defy fate together, but can love survive a nation’s fall?',2700,'/assets/backdrops/tv_289139.jpg') ON CONFLICT (id) DO NOTHING;
