INSERT INTO episodes (id,title_id,season,number,name,synopsis,duration,thumbnail) VALUES (115,40,1,1,'Chapter One','2029, a near-future Japan. The full cyborg Motoko Kusanagi envisions a task force that preemptively strikes emerging threats. She and her team are scouted by Daisuke Aramaki as Public Security Section 9, AKA the "Shell Squad." An international conspiracy hints at a hacker known as The "Puppet Master." What fate awaits Kusanagi? What is the hacker''s endgame? A new era of cyberpunk action begins!',2700,'/assets/backdrops/tv_255358.jpg') ON CONFLICT (id) DO NOTHING;
