INSERT INTO episodes (id,title_id,season,number,name,synopsis,duration,thumbnail) VALUES (145,53,1,1,'Chapter One','David Letterman uses mature humor to appeal to his audience in this weeknight series, which gets its music from a house band led by Paul Shaffer. Among the show''s most-famous segments are the Top Ten List and Stupid Pet Tricks, the latter of which subsequently led to an additional recurring segment called Stupid Human Tricks.',2700,'/assets/backdrops/tv_498.jpg') ON CONFLICT (id) DO NOTHING;
