INSERT INTO episodes (id,title_id,season,number,name,synopsis,duration,thumbnail) VALUES (151,54,1,1,'Chapter One','The Tonight Show Starring Johnny Carson is a talk show hosted by Johnny Carson under The Tonight Show franchise from 1962 to 1992. It originally aired during late-night. For its first ten years, Carson''s Tonight Show was based in New York City with occasional trips to Burbank, California; in May 1972, the show moved permanently to Burbank, California. In 2002, The Tonight Show Starring Johnny Carson was ranked #12 on TV Guide''s 50 Greatest TV Shows of All Time.',2700,'/assets/backdrops/tv_2261.jpg') ON CONFLICT (id) DO NOTHING;
