INSERT INTO episodes (id,title_id,season,number,name,synopsis,duration,thumbnail) VALUES (181,59,1,1,'Chapter One','Stephen Colbert brings his signature satire and comedy to The Late Show with Stephen Colbert, the #1 show in late night, where he talks with an eclectic mix of guests about what is new and relevant in the worlds of politics, entertainment, business, music, technology, and more. Featuring bandleader Jon Batiste with his band Stay Human, the Emmy Award-nominated show is broadcast from the historic Ed Sullivan Theater.',2700,'/assets/backdrops/tv_63770.jpg') ON CONFLICT (id) DO NOTHING;
